<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b141a"><title>Agencia Selena · Resultados</title><style>
:root{color-scheme:dark;--bg:#0b141a;--panel:#111b21;--panel2:#202c33;--line:#2a3942;--text:#e9edef;--muted:#91a6af;--green:#00a884;--lime:#25d366;--yellow:#f7c948}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,-apple-system,Segoe UI,Arial,sans-serif}.shell{max-width:1220px;margin:auto;padding:0 22px 65px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:23px 0 20px;border-bottom:1px solid var(--line)}.brand{display:flex;gap:13px;align-items:center}.brand-icon{width:48px;height:48px;border-radius:15px;background:linear-gradient(140deg,#25d366,#008069);display:grid;place-items:center;color:#071b13;font-size:26px}.brand-icon{overflow:hidden;background:transparent;border-radius:50%}.brand-icon img{display:block;width:100%;height:100%;object-fit:contain}.brand strong{font-size:21px;letter-spacing:-.6px}.brand small{display:block;color:var(--muted);margin-top:3px}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}button,input{font:inherit}button{cursor:pointer}.btn{border:1px solid var(--line);background:var(--panel2);color:var(--text);border-radius:10px;padding:10px 15px;font-weight:650}.btn:hover,.tab:hover{border-color:#517169}.btn.green{background:var(--green);color:white;border-color:var(--green)}.btn:disabled{opacity:.45;cursor:not-allowed}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:27px 0 15px}.section-head h2{margin:0;font-size:21px;letter-spacing:-.5px}.section-head p{margin:4px 0 0;color:var(--muted);font-size:13px}.status{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:12px}.dot{background:var(--yellow);height:7px;width:7px;border-radius:50%}.dot.ok{background:var(--lime)}.hero{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:20px}.latest{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:13px}.result{position:relative;min-width:0;background:#18262c;border:1px solid #304249;border-radius:14px;padding:16px 8px 13px;text-align:center;transition:.2s}.result:hover{transform:translateY(-2px);border-color:#3e8b75}.result .star{position:absolute;right:7px;top:7px;border:0;background:transparent;color:#68818a;font-size:21px;line-height:24px;padding:0 1px;z-index:1}.result .star.active{color:var(--yellow)}.animal-icon img{height:100%;width:100%;object-fit:contain;border-radius:50%;display:block}.animal-icon{height:65px;width:65px;border-radius:50%;display:grid;place-items:center;margin:7px auto 12px;background:radial-gradient(circle at 30% 25%,#3e6252,#16342b);border:2px solid #336955;font-size:32px}.result .lottery{font-size:12px;font-weight:750;line-height:1.4;overflow-wrap:anywhere;min-height:33px}.result .hour{color:#9eb5be;font-size:12px;margin:7px 0}.result .value{font-size:24px;font-weight:800;color:var(--lime);letter-spacing:-.5px}.result .animal{font-size:12px;color:var(--text);margin-top:3px;overflow-wrap:anywhere}.panel-note{font-size:12px;color:var(--muted);margin-top:15px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:24px 0 16px}.toolbar h2{font-size:21px;margin:0}.filters{display:flex;gap:9px;flex-wrap:wrap}.search{border:1px solid var(--line);background:var(--panel);color:var(--text);border-radius:10px;padding:11px 13px;min-width:235px;outline:none}.search:focus{border-color:var(--green)}.tabs{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:16px}.tab{padding:9px 13px;background:var(--panel);color:var(--muted);border:1px solid var(--line);border-radius:40px;font-weight:650}.tab.active{background:#123e33;border-color:#207d5f;color:#a6f3cc}.groups{display:grid;gap:11px}.group{background:var(--panel);border:1px solid var(--line);border-radius:13px;overflow:hidden}.group-head{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:17px 19px;width:100%;background:transparent;border:none;color:var(--text);text-align:left}.group-head:hover{background:#19272d}.gname{display:flex;align-items:center;gap:12px;font-weight:750;font-size:15px}.gicon{display:grid;place-items:center;width:39px;height:39px;border-radius:11px;background:#174737;color:#76e8b2;font-size:18px}.gmeta{font-size:12px;color:var(--muted);margin-top:3px;font-weight:400}.chevron{transition:transform .2s;font-size:20px;color:var(--muted)}.group.open .chevron{transform:rotate(180deg)}.group-body{padding:0 17px 20px;display:none}.group.open .group-body{display:block}.draws{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:11px}.draw{background:#192930;border:1px solid #30434b;border-radius:11px;padding:15px 7px;text-align:center}.draw .time{font-size:12px;color:#9bb1ba;font-weight:750}.draw .num{margin:9px 0 4px;font-size:26px;font-weight:800;color:var(--lime)}.draw .name{font-size:12px}.draw.empty{opacity:.7}.empty-state{border:1px dashed #45615c;background:#15252a;border-radius:14px;text-align:center;color:var(--muted);padding:37px 16px;grid-column:1/-1}.foot{color:var(--muted);font-size:12px;margin:25px 0;text-align:center}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);border-radius:12px;padding:12px 20px;background:#1f4237;color:#c6ffe5;box-shadow:0 6px 30px #0007;display:none;z-index:3;max-width:94vw}.toast.show{display:block}@media(max-width:1060px){.latest{grid-template-columns:repeat(4,1fr)}.draws{grid-template-columns:repeat(5,1fr)}}@media(max-width:700px){.shell{padding:0 12px 45px}.top{align-items:flex-start;flex-direction:column}.brand strong{font-size:18px}.hero{padding:12px}.latest{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.result{padding:12px 4px}.animal-icon{width:49px;height:49px;font-size:25px}.result .lottery{font-size:11px}.draws{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.group-head{padding:13px}.toolbar{align-items:stretch}.filters,.search{width:100%}.search{min-width:0}.btn{padding:9px 11px}.section-head h2,.toolbar h2{font-size:19px}}

/* Tarjetas cuadradas con la fotografía a tamaño completo */
.latest .result{aspect-ratio:1/1;min-height:0;padding:0;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;isolation:isolate;overflow:hidden;border-radius:12px;background:#15272a;box-shadow:0 3px 10px #0004;transform:none}
.latest .result .animal-icon{position:absolute;inset:0;margin:0;width:100%;height:100%;border:0;border-radius:0;background:#153f32;display:grid;place-items:center;font-size:64px;z-index:-2}
.latest .result .animal-icon img{width:100%;height:100%;object-fit:cover;border-radius:0}
.latest .result:before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:linear-gradient(to bottom,rgba(5,13,17,.15) 0%,transparent 28%,rgba(5,13,17,.50) 51%,rgba(4,11,14,.96) 100%)}
.latest .result .lottery,.latest .result .hour,.latest .result .value,.latest .result .animal{position:relative;z-index:1;text-shadow:0 1px 4px #000,0 1px 2px #000;margin:0;min-height:0;width:100%;padding:0 5px}
.latest .result .lottery{font-size:13px;line-height:1.2;font-weight:800;margin-bottom:4px}
.latest .result .hour{font-size:11px;color:#e7f0f1;margin-bottom:1px}
.latest .result .value{font-size:28px;line-height:1.08;color:#40ef90}
.latest .result .animal{font-size:12px;font-weight:700;margin-top:2px;margin-bottom:9px}
.latest .result .star{z-index:3;top:6px;right:6px;width:30px;height:30px;border-radius:8px;background:rgba(8,20,25,.78);color:#e4f6f2;text-shadow:0 1px 2px #000;display:grid;place-items:center}
.latest .result .star.active{color:#ffcd40;background:rgba(8,20,25,.87)}
@media(max-width:700px){.latest .result .lottery{font-size:10px}.latest .result .animal{font-size:10px;margin-bottom:5px}.latest .result .value{font-size:21px}.latest .result .hour{font-size:9px}.latest .result .star{width:23px;height:23px;top:3px;right:3px;font-size:18px}.latest .result .animal-icon{font-size:40px}}

/* Imagen completa también para Lotoven; el contenido de la imagen puede traer márgenes propios. */
#lotoven-latest .result{aspect-ratio:1/1;overflow:hidden;border-radius:12px}
#lotoven-latest .result .animal-icon{position:absolute;inset:0;width:100%;height:100%;margin:0;border-radius:0;overflow:hidden;background:#153b30}
#lotoven-latest .result .animal-icon img{display:block;width:100%;height:100%;object-fit:cover;object-position:center;image-rendering:auto;filter:none;border-radius:0;transform:scale(1.28);transform-origin:center 42%}
#lotoven-latest .result .lottery,#lotoven-latest .result .hour,#lotoven-latest .result .value,#lotoven-latest .result .animal{z-index:1}
#lotoven-latest .result::before{background:linear-gradient(to bottom,rgba(2,10,12,.16),transparent 33%,rgba(2,10,12,.48) 57%,rgba(2,10,12,.97) 100%)}
/* Sin filtros de desenfoque: los archivos originales siguen determinando la nitidez real. */

/* v siguiente: foto pequeña sin ampliaciones + pie sólido sin fotografía de fondo */
.latest .result, #lotoven-latest .result {
  aspect-ratio: 1 / 1; display:flex; flex-direction:column;
  justify-content:flex-end; align-items:stretch; padding:0;
  position:relative; isolation:isolate; overflow:hidden;
  background:#142329; border-radius:12px;
}
.latest .result .animal-icon, #lotoven-latest .result .animal-icon {
  position:absolute; left:0; top:0; right:0; bottom:auto;
  width:100%; height:62%; margin:0; padding:10px 18px 2px;
  display:flex; justify-content:center; align-items:center;
  background:#12372f; border:0; border-radius:0;
  z-index:0; font-size:38px; overflow:hidden;
}
.latest .result .animal-icon img, #lotoven-latest .result .animal-icon img {
  display:block; width:100%; height:100%; object-fit:contain;
  object-position:center; max-height:100%; max-width:100%;
  border-radius:0; transform:none; filter:none; image-rendering:auto;
}
.latest .result:before, #lotoven-latest .result:before {content:none!important; display:none!important}
.latest .result .lottery, .latest .result .hour,
.latest .result .value, .latest .result .animal,
#lotoven-latest .result .lottery, #lotoven-latest .result .hour,
#lotoven-latest .result .value, #lotoven-latest .result .animal {
  position:relative; z-index:2; flex-shrink:0;
  background:#111b21; text-shadow:none;
  width:100%; margin:0; padding:0 5px; text-align:center;
}
.latest .result .lottery {padding-top:8px; font-size:12px; min-height:0}
.latest .result .hour {font-size:10px; padding-top:2px; color:#c2d6d9}
.latest .result .value {font-size:25px; line-height:1.1; padding-top:3px}
.latest .result .animal {font-size:11px; padding:1px 5px 9px; font-weight:700}
.latest .result .star {z-index:4}
@media(max-width:700px){
  .latest .result .animal-icon, #lotoven-latest .result .animal-icon {height:57%;padding:7px}
  .latest .result .lottery {font-size:10px;padding-top:4px}
  .latest .result .hour {font-size:9px}
  .latest .result .value {font-size:20px}
  .latest .result .animal {font-size:9px;padding-bottom:5px}
}

/* El tercer panel reutiliza el diseño de tarjetas y pies opacos. */
#hoy-latest .result{aspect-ratio:1/1;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;padding:0;position:relative;isolation:isolate;overflow:hidden;background:#142329}
#hoy-latest .result .animal-icon{position:absolute;left:0;top:0;right:0;bottom:auto;width:100%;height:62%;margin:0;padding:10px 18px 2px;display:flex;justify-content:center;align-items:center;background:#12372f;border:0;border-radius:0;z-index:0;overflow:hidden;font-size:38px}
#hoy-latest .result .animal-icon img{display:block;width:100%;height:100%;object-fit:contain;object-position:center;border-radius:0;transform:none;filter:none}
#hoy-latest .result:before{display:none!important;content:none!important}
#hoy-latest .result .lottery,#hoy-latest .result .hour,#hoy-latest .result .value,#hoy-latest .result .animal{position:relative;z-index:1;background:#101c22;width:100%;margin:0;padding-left:4px;padding-right:4px;text-shadow:none;min-height:0}
#hoy-latest .result .lottery{padding-top:8px;font-size:12px;line-height:1.25}
#hoy-latest .result .hour{font-size:11px;padding-top:1px}
#hoy-latest .result .value{font-size:26px;line-height:1.17;padding-top:4px}
#hoy-latest .result .animal{font-size:12px;padding-top:1px;padding-bottom:8px}
#hoy-latest .result .star{z-index:3}
.group{position:relative}.group>.pin-btn{position:absolute;top:11px;right:43px;z-index:2}.group-head{padding-right:100px}.pin-btn{border:1px solid #375349;background:#17382e;color:#9cddc3;padding:8px 10px;border-radius:10px;cursor:pointer;font-size:18px}
.pin-btn.active{color:#ffd56c;border-color:#e7aa34;background:#4b3b18}
.group-actions{display:flex;align-items:center;gap:9px}.featured{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}
.featured .result{min-width:0}.featured-title{font-weight:700;color:#c0f8da}
@media(max-width:700px){.featured{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}#hoy-latest .result .lottery{font-size:10px;padding-top:4px}#hoy-latest .result .hour{font-size:9px}#hoy-latest .result .value{font-size:21px}#hoy-latest .result .animal{font-size:10px;padding-bottom:5px}}

/* Encabezado primero; acordeones plegados al iniciar */
.section-head:first-of-type{margin-top:18px}
.source-accordion{border:1px solid var(--line);border-radius:14px;background:var(--panel);margin:11px 0;overflow:hidden}
.source-heading{width:100%;border:0;background:transparent;color:var(--text);padding:16px;display:flex;align-items:center;gap:12px;text-align:left}
.source-heading:hover{background:#1b2a30}
.source-heading strong{display:block;font-size:16px}.source-heading small{display:block;margin-top:4px;color:var(--muted);font-size:12px}
.source-mark{width:39px;height:39px;display:grid;place-items:center;background:#174737;border-radius:10px;font-size:21px}
.source-right{margin-left:auto;display:flex;gap:15px;align-items:center;font-size:12px;color:var(--muted)}.source-arrow{font-size:25px;transition:transform .2s}.source-heading[aria-expanded=true] .source-arrow{transform:rotate(180deg)}
.source-content{border:0;border-top:1px solid var(--line);border-radius:0}.source-content[hidden]{display:none!important}
.logo-thumbnail{overflow:hidden;background:#123f33;border:1px solid #346453}.logo-thumbnail img{width:100%;height:100%;object-fit:contain;border-radius:50%}
.latest .comparison-match{border:2px solid #28df76;box-shadow:0 0 13px #28df765c}.latest .comparison-mismatch{border:2px solid #ff5159;box-shadow:0 0 13px #ff515963}.latest .comparison-unknown{border:1px solid #304249}
.featured{margin-bottom:6px}.featured .result{border-radius:12px}
@media(max-width:700px){.source-right{font-size:10px;gap:6px}.source-heading{padding:12px}.source-heading strong{font-size:14px}}

.source-accordion.source-match{border-color:#21e17d;box-shadow:0 0 17px #21e17d75;animation:greenPulse 2.2s ease-in-out infinite}
.source-accordion.source-mismatch{border-color:#ff5353;box-shadow:0 0 16px #ff53536c;animation:redPulse 2.2s ease-in-out infinite}
.source-accordion.source-unknown{border-color:var(--line);box-shadow:none}
@keyframes greenPulse{50%{box-shadow:0 0 24px #22dd83bd}}@keyframes redPulse{50%{box-shadow:0 0 24px #ff5353b3}}
.source-verdict{font-size:12px;font-weight:700;margin-left:7px}.source-match .source-verdict{color:#68ffa7}.source-mismatch .source-verdict{color:#ff8383}

.bottom-actions{display:flex;justify-content:flex-end;align-items:center;gap:10px;padding:18px 0 8px;margin-top:20px;border-top:1px solid var(--line)}
.featured{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:13px}
@media(max-width:700px){.featured{grid-template-columns:repeat(2,minmax(0,1fr))}.bottom-actions{justify-content:center}.bottom-actions .status{width:100%;justify-content:center}}

/* Controles al lado de los encabezados y acceso a WhatsApp */
.top{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}
.header-whatsapp{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;background:#00a884;color:#fff;border-radius:9px;padding:12px 18px;font-weight:800;font-size:14px;min-height:42px;box-shadow:0 2px 9px #00a88425}
.header-whatsapp:hover,.header-whatsapp:focus-visible{background:#06c398;outline:2px solid #53f6c4;outline-offset:2px}
.section-head.with-actions{display:flex;align-items:center;justify-content:space-between;gap:14px}
.section-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}
.section-actions .status{white-space:nowrap}
.section-actions .btn{white-space:nowrap}
@media(max-width:660px){.header-whatsapp{width:100%}.section-head.with-actions{flex-direction:column;align-items:stretch}.section-actions{justify-content:flex-start}.section-actions .status{font-size:11px}}

/* Señala la vigencia horaria del resultado, calculada en Venezuela. */
#featured .result.freshness-fresh,#intermedias .result.freshness-fresh{border:2px solid #32f78e!important;box-shadow:0 0 13px rgba(38,244,126,.65),inset 0 0 12px rgba(38,244,126,.12)!important}
#featured .result.freshness-stale,#intermedias .result.freshness-stale{border:2px solid #ff4258!important;box-shadow:0 0 13px rgba(255,56,76,.66),inset 0 0 12px rgba(255,56,76,.12)!important}
#featured .result.freshness-future,#intermedias .result.freshness-future{border-color:#567884!important}

/* Selena 2: movilidad, estado verificable y nueva barra de herramientas */
@media(max-width:760px){.shell{width:100%;max-width:100%;padding:12px!important}.top{flex-wrap:wrap;gap:10px}.brand{min-width:0}.featured,.latest{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:9px!important}.result{min-width:0!important;width:auto!important}.source-heading{gap:9px}.toolbar{flex-wrap:wrap;gap:8px}.filters{width:100%}.filters input{min-width:0;flex:1}.section-head.with-actions{gap:8px}.section-actions{flex-wrap:wrap}.btn{min-height:40px}}
@media(max-width:390px){.featured,.latest{grid-template-columns:repeat(2,minmax(0,1fr))!important}.result{padding:8px 3px!important}.section-actions .btn{font-size:12px;padding:8px}}
.result.new-result{animation:newSelena 1.7s ease-in-out 2}@keyframes newSelena{50%{box-shadow:0 0 20px #16e38d}}
.quality{font-size:11px;margin-top:6px;color:#c4d4d9}.quality.ok{color:#45ed9d}.quality.conflict{color:#ff6e76}.source-heading.status-match{box-shadow:inset 4px 0 #36ed99}.source-heading.status-mismatch{box-shadow:inset 4px 0 #ff4e68}
.small-tools{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 14px}.small-tools button{font:inherit}.mini-meta{font-size:11px;color:#9bb6b6}.dialog-screen{position:fixed;inset:0;background:#000b;display:flex;align-items:center;justify-content:center;z-index:100;padding:16px}.dialog-panel{max-width:580px;width:100%;background:#182930;border:1px solid #37545b;border-radius:14px;padding:18px}.dialog-panel textarea{width:100%;min-height:245px;margin:10px 0;background:#09171c;color:#e9faf5;border:1px solid #42606a;border-radius:7px;padding:12px;font:13px/1.5 monospace}

/* Square photos fill each card; the full animal remains visible. */
.featured .result,.latest .result,#lotoven-latest .result,#hoy-latest .result{aspect-ratio:auto;display:flex;flex-direction:column;justify-content:flex-start;align-items:stretch;padding:0!important;overflow:hidden}
.result .animal-icon,#lotoven-latest .result .animal-icon,#hoy-latest .result .animal-icon{position:relative!important;inset:auto!important;display:grid!important;place-items:center;width:100%!important;height:auto!important;aspect-ratio:1/1;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:#16332f;overflow:hidden;z-index:0;font-size:14px}
.result .animal-icon img,#lotoven-latest .result .animal-icon img,#hoy-latest .result .animal-icon img{display:block;width:100%;height:100%;max-width:100%;max-height:100%;aspect-ratio:1/1;object-fit:contain;object-position:center;border-radius:0!important;transform:none!important}
.result .lottery{padding:9px 6px 3px!important;min-height:0;font-size:13px!important;line-height:1.3}
.result .hour{margin:0;padding:2px 5px!important;font-size:12px!important}
.result .value{padding:3px 5px!important;font-size:28px!important;line-height:1.15}
.result .animal{margin:0;padding:2px 5px 10px!important;font-size:12px!important}
.result .winner-source{font-size:10px;color:#a7cbbd;padding:0 5px 9px;text-align:center}
.result .star{z-index:4;background:#0b141acc;border-radius:7px}
@media(max-width:760px){.result .lottery{font-size:12px!important}.result .value{font-size:25px!important}}

